async function poll(){if(polling||!token)return;polling=true;const begin=performance.now();try{const next=await api('/api/state',{timeout:5500});if(!token)return;if(next.protocol!==2)throw new Error('Mettez à jour le studio Windows pour utiliser cette console.');acceptState(next);$('#connection').textContent=next.fresh?'Connecté au studio':'Studio sans réponse';$('#connection').className=next.fresh?'live':'';$('#latency').textContent=Math.round(performance.now()-begin)+' ms · son sur le PC';if(!next.fresh){connectionNotice=true;notice('Le studio ne répond plus. Commandes suspendues.');}else if(connectionNotice||$('#notice').textContent==='Connexion au studio…'){connectionNotice=false;notice('');}render();}catch(error){connected=false;connectionNotice=true;$('#connection').textContent='Connexion interrompue';$('#connection').className='';notice(error.message||'Vérifiez le réseau et le studio du PC.');controls();}finally{polling=false;}}
controls();if(token){notice('Connexion au studio…');poll();}else notice('Ouvrez le lien d’appairage affiché dans Remote sur le PC.');setInterval(poll,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});

