window.addEventListener('keydown',e=>{if(e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA','AUDIO'].includes(document.activeElement.tagName)||!connected||!state?.fresh)return;if(e.code==='Space'&&!document.activeElement.matches('button,a')){e.preventDefault();act({type:'deck:toggle',deck:e.shiftKey?1:0});}else if(e.key.toLowerCase()==='t'){e.preventDefault();act({type:state.transition.active?'transition:cancel':'transition:start'});}else if(/^[1-8]$/.test(e.key)&&!e.repeat){const n=Number(e.key)-1;act({type:'deck:hotcue',deck:n<4?0:1,slot:n%4,action:e.shiftKey?'clear':'trigger'});}else if(['ArrowLeft','ArrowRight'].includes(e.key)&&document.activeElement.tagName!=='CANVAS'){e.preventDefault();act({type:'mixer:crossfader',value:clamp(state.crossfader+(e.key==='ArrowRight'?.05:-.05),0,1)});}});

