function acceptState(next){if(!token||!next||!Array.isArray(next.decks)||next.revision<(state?.revision||0))return;const age=Math.min(500,Math.max(0,(next.serverNow||next.updatedAt||0)-(next.capturedAt||next.updatedAt||0)));state=next;receivedAt=performance.now()-age;connected=true;$('#connection').textContent=next.fresh?'Connecté au studio':'Studio sans réponse';$('#connection').className=next.fresh?'live':'';render();}
async function streamStates(){if(!token||streamController)return;const controller=new AbortController();streamController=controller;try{const response=await fetch('/api/events',{headers:{Authorization:'Bearer '+token},cache:'no-store',signal:controller.signal});if(!response.ok||!response.body)throw Error('Flux indisponible');streamConnected=true;const reader=response.body.getReader(),decoder=new TextDecoder();let pending='';while(token){const {value,done}=await reader.read();if(done)break;pending+=decoder.decode(value,{stream:true});let end;while((end=pending.indexOf('\n\n'))>=0){const event=pending.slice(0,end);pending=pending.slice(end+2);const data=event.split('\n').find(line=>line.startsWith('data: '));if(data)try{acceptState(JSON.parse(data.slice(6)));}catch{}}}}catch{}finally{streamConnected=false;streamController=null;if(token)setTimeout(streamStates,1500);}}
if(token)streamStates();window.addEventListener('pagehide',()=>streamController?.abort(),{once:true});
